'use strict';

// FUNCTIONS //

/**
* Comparator function to sort pairs in ascending order by value.
*
* @private
* @param {Array} a - first pair
* @param {Array} b - second pair
* @returns {number} difference between first elements
*/
function ascending( a, b ) {
	return a[ 0 ] - b[ 0 ];
}


// MAIN //

/**
* Computes the ranks of values in an array, handling ties by averaging.
*
* @private
* @param {NumericArray} x - input data array
* @returns {Array<number>} array of ranks
*
* @example
* var x = [ 3.0, 1.0, 2.0, 2.0 ];
* var r = rankData( x );
* // returns [ 4.0, 1.0, 2.5, 2.5 ]
*/
function rankData( x ) {
	var sorted;
	var ranks;
	var sum;
	var cnt;
	var n;
	var i;
	var j;

	n = x.length;

	// Create an array of [value, originalIndex] pairs:
	sorted = [];
	for ( i = 0; i < n; i++ ) {
		sorted.push( [ x[ i ], i ] );
	}

	// Sort by value:
	sorted.sort( ascending );

	// Assign ranks, averaging tied values:
	ranks = [];
	i = 0;
	while ( i < n ) {
		j = i;

		// Find the group of tied values:
		while ( j < n - 1 && sorted[ j ][ 0 ] === sorted[ j + 1 ][ 0 ] ) {
			j += 1;
		}
		// Compute the average rank for the tied group:
		cnt = j - i + 1;
		sum = 0;
		for ( j = i; j < i + cnt; j++ ) {
			sum += j + 1; // Ranks are 1-based
		}
		// Assign the average rank to each tied element:
		for ( j = i; j < i + cnt; j++ ) {
			ranks[ sorted[ j ][ 1 ] ] = sum / cnt;
		}
		i += cnt;
	}
	return ranks;
}


// EXPORTS //

module.exports = rankData;
